16	export function mapFilePath(filePath: string) {
17	  if (filePath.startsWith('!')) {
18	    const fileWithoutBang = filePath.slice(1);
19	    if (fileWithoutBang.startsWith('*.')) {
20	      return `!${joinPathFragments('**', fileWithoutBang)}`;
21	    }
22	    return filePath;
23	  }
24	  if (filePath.startsWith('*.')) {
25	    return joinPathFragments('**', filePath);
26	  }
27	  return filePath;
