function updateNxJsonConfig(tree: Tree, format: 'cjs' | 'mjs') {
  if (tree.exists('nx.json')) {
    updateJson(tree, 'nx.json', (json: NxJsonConfiguration) => {
      // rewrite stale legacy eslint filename references in target defaults
      if (json.targetDefaults) {
        for (const target of Object.keys(json.targetDefaults)) {
          if (Array.isArray(json.targetDefaults[target].inputs)) {
            json.targetDefaults[target].inputs = renameEslintInputs(
              json.targetDefaults[target].inputs,
              format
            );
          }
        }
      }
      // rewrite stale legacy eslint filename references in named inputs
      if (json.namedInputs) {
        for (const namedInput of Object.keys(json.namedInputs)) {
          json.namedInputs[namedInput] = renameEslintInputs(
            json.namedInputs[namedInput],
            format
          );
        }
      }

      if (json.targetDefaults?.lint?.inputs) {
        const inputSet = new Set(json.targetDefaults.lint.inputs);
        inputSet.add(`{workspaceRoot}/eslint.config.${format}`);
        json.targetDefaults.lint.inputs = Array.from(inputSet);
      }
      if (json.targetDefaults?.['@nx/eslint:lint']?.inputs) {
        const inputSet = new Set(json.targetDefaults['@nx/eslint:lint'].inputs);
        inputSet.add(`{workspaceRoot}/eslint.config.${format}`);
        json.targetDefaults['@nx/eslint:lint'].inputs = Array.from(inputSet);
      }
      if (json.namedInputs?.production) {
        const inputSet = new Set(json.namedInputs.production);
        inputSet.add(`!{projectRoot}/eslint.config.${format}`);
        json.namedInputs.production = Array.from(inputSet);
      }
      return json;
    });
  }
}

// rewrite stale legacy eslint filename references in the projects' targets
// inputs and namedInputs
function updateProjectsInputs(tree: Tree, format: 'cjs' | 'mjs') {
  const projects = getProjects(tree);
  for (const [project, projectConfig] of projects) {
    let updated = false;

    if (projectConfig.targets) {
      for (const target of Object.keys(projectConfig.targets)) {
        if (Array.isArray(projectConfig.targets[target].inputs)) {
          projectConfig.targets[target].inputs = renameEslintInputs(
            projectConfig.targets[target].inputs,
            format
          );
          updated = true;
        }
      }
    }

    if (projectConfig.namedInputs) {
      for (const namedInput of Object.keys(projectConfig.namedInputs)) {
        projectConfig.namedInputs[namedInput] = renameEslintInputs(
          projectConfig.namedInputs[namedInput],
          format
        );
        updated = true;
      }
    }

    if (updated) {
      updateProjectConfiguration(tree, project, projectConfig);
    }
  }
}

// rewrites legacy eslint filename references within a single inputs array,
// preserving negation prefixes, leaving non-string entries untouched, and
// deduplicating string entries after the rewrite.
function renameEslintInputs<T>(inputs: T[], format: 'cjs' | 'mjs'): T[] {
  const seen = new Set<string>();
  const result: T[] = [];
  for (const input of inputs) {
    if (typeof input !== 'string') {
      result.push(input);
      continue;
    }
    const renamed = renameEslintReference(input, format);
    if (seen.has(renamed)) {
      continue;
    }
    seen.add(renamed);
    result.push(renamed as unknown as T);
  }
  return result;
}

// maps a single legacy eslint filename reference to its flat config equivalent,
// preserving any negation prefix and path prefix. Returns the input unchanged
// when it does not reference a legacy eslint filename.
function renameEslintReference(input: string, format: 'cjs' | 'mjs'): string {
  const isNegated = input.startsWith('!');
  const path = isNegated ? input.slice(1) : input;

  let renamed: string | undefined;
  if (path.endsWith('.eslintrc.base.json')) {
    renamed = path.replace(
      /\.eslintrc\.base\.json$/,
      `eslint.base.config.${format}`
    );
  } else if (path.endsWith('.eslintrc.json')) {
    renamed = path.replace(/\.eslintrc\.json$/, `eslint.config.${format}`);
  } else if (path.endsWith('.eslintignore')) {
    renamed = path.replace(/\.eslintignore$/, `eslint.config.${format}`);
  }

  if (renamed === undefined) {
    return input;
  }
  return isNegated ? `!${renamed}` : renamed;
