+{"version":3,"sources":["/workspace/repo/packages/nx/src/plugins/js/lock-file/yarn-parser.ts"],"sourcesContent":["import {\n  getHoistedPackageVersion,\n  NormalizedPackageJson,\n} from './utils/package-json';\nimport {\n  RawProjectGraphDependency,\n  validateDependency,\n} from '../../../project-graph/project-graph-builder';\nimport { gt, Range, satisfies } from 'semver';\nimport {\n  DependencyType,\n  ProjectGraph,\n  ProjectGraphExternalNode,\n  ProjectGraphProjectNode,\n} from '../../../config/project-graph';\nimport { hashArray } from '../../../hasher/file-hasher';\nimport { sortObjectByKeys } from '../../../utils/object-sort';\nimport { CreateDependenciesContext } from '../../../project-graph/plugins';\nimport { getWorkspacePackagesFromGraph } from '../utils/get-workspace-packages-from-graph';\n\n/**\n * Yarn\n * - Classic has resolved and integrity\n * - Berry has resolution, checksum, languageName and linkType\n */\ntype YarnDependency = {\n  version: string;\n  dependencies?: Record<string, string>;\n  optionalDependencies?: Record<string, string>;\n  peerDependencies?: Record<string, string>;\n\n  // classic specific\n  resolved?: string;\n  integrity?: string;\n\n  // berry specific\n  resolution?: string;\n  checksum?: string;\n  languageName?: string;\n  linkType?: 'soft' | 'hard';\n};\n\nlet currentLockFileHash: string;\nlet cachedParsedLockFile;\n\nfunction parseLockFile(lockFileContent: string, lockFileHash: string) {\n  if (currentLockFileHash === lockFileHash) {\n    return cachedParsedLockFile;\n  }\n\n  const { parseSyml } =\n    require('../../../utils/yarn-syml') as typeof import('../../../utils/yarn-syml');\n\n  const result = parseSyml(lockFileContent);\n  cachedParsedLockFile = result;\n  currentLockFileHash = lockFileHash;\n  return result;\n}\n\nexport function getYarnLockfileNodes(\n  lockFileContent: string,\n  lockFileHash: string,\n  packageJson: NormalizedPackageJson\n): {\n  nodes: Record<string, ProjectGraphExternalNode>;\n  keyM