+{"version":3,"sources":["/workspace/repo/packages/nx/src/project-graph/project-graph.ts"],"sourcesContent":["import { performance } from 'perf_hooks';\n\nimport { join } from 'path';\nimport { customDimensions } from '../analytics';\nimport { readNxJson } from '../config/nx-json';\nimport { ProjectGraph } from '../config/project-graph';\nimport {\n  ProjectConfiguration,\n  ProjectsConfigurations,\n} from '../config/workspace-json-project-json';\nimport { daemonClient } from '../daemon/client/client';\nimport { isOnDaemon } from '../daemon/is-on-daemon';\nimport { markDaemonAsDisabled, writeDaemonLogs } from '../daemon/tmp-dir';\nimport { FileLock, IS_WASM } from '../native';\nimport { workspaceDataDirectory } from '../utils/cache-directory';\nimport { getCallSites } from '../utils/call-sites';\nimport { DelayedSpinner } from '../utils/delayed-spinner';\nimport { fileExists } from '../utils/fileutils';\nimport { logger } from '../utils/logger';\nimport { output } from '../utils/output';\nimport { stripIndents } from '../utils/strip-indents';\nimport { workspaceRoot } from '../utils/workspace-root';\nimport {\n  buildProjectGraphUsingProjectFileMap,\n  hydrateFileMap,\n} from './build-project-graph';\nimport {\n  AggregateProjectGraphError,\n  isAggregateProjectGraphError,\n  ProjectConfigurationsError,\n  ProjectGraphError,\n  StaleProjectGraphCacheError,\n} from './error-types';\nimport {\n  readFileMapCache,\n  readProjectGraphCache,\n  readSourceMapsCache,\n  writeCache,\n} from './nx-deps-cache';\nimport { getPlugins } from './plugins/get-plugins';\nimport { ConfigurationResult } from './utils/project-configuration-utils';\nimport {\n  retrieveProjectConfigurations,\n  retrieveWorkspaceFiles,\n} from './utils/retrieve-workspace-files';\nimport { handleImport } from '../utils/handle-import';\n\n/**\n * Synchronously reads the latest cached copy of the workspace's ProjectGraph.\n *\n * @param {number} [minimumComputedAt] - The minimum timestamp that the cached Pr